// ===========================================================================
// SSR DİL TABLOSU — 46 dil (tr + 45)                        29 Ağustos 2026
// ===========================================================================
// NEDEN VAR: 29 Ağu 2026'ya kadar SSR **tek dilliydi**. `?dil=en` de,
// `Accept-Language: en` de aynı Türkçe sayfayı üretiyordu; sebebi bu dosyanın
// yokluğuydu — SSS soruları, künye etiketleri, başlık/açıklama şablonları
// Türkçe DİZGİ olarak server.js'e gömülüydü ve uygulamanın `app/lib/diller/`
// sözlükleriyle hiçbir bağı yoktu (ANAHTAR-KELIME-ENVANTERI.md §4.2 md.1).
//
// TEMEL KURAL — YARIM ÇEVİRİ YASAK:
//   Bir dil bu tabloda ya TAM vardır ya HİÇ yoktur. Eksik anahtar Türkçeye
//   düşmez; düşseydi Almanca sayfanın ortasında Türkçe cümle çıkardı ve o
//   sayfa hiçbir motorda işe yaramazdı (ince/karma içerik). `seoDilVar()`
//   bunun kapısıdır: tabloda olmayan dil için dil önekli URL üretilmez,
//   hreflang'e girmez, site haritasına yazılmaz.
//
// TMDB ÇEVİRİSİ AYRI BİR KONU: yapım özeti/başlığı TMDB'den `?language=xx`
// ile gelir. TMDB o dilde çeviri vermiyorsa alan BOŞ kalır — Türkçesi
// BASILMAZ (server.js `seoCeviriAlani` yalnız 'en' yedeğine düşer, 'tr'ye
// asla). Bu dosya yalnız BİZİM yazdığımız metni taşır.
//
// ---------------------------------------------------------------------------
// SAYI, TARİH VE ÜLKE ADLARI: ICU (elle tablo YOK)
// ---------------------------------------------------------------------------
// `seoTarihTr` 12 Türkçe ay adını elle taşıyordu. 46 dil için bu 552 ay adı
// + 46 tarih sırası + 46 binlik ayracı + 46 × 40 ülke adı demekti. Hepsi
// ICU'da ZATEN var ve Node 22 tam ICU ile geliyor (canlı doğrulandı:
// `process.versions.icu = 78.2`).
//
// ⚠ AÇIKÇA VERİLEN YEREL ŞART: eski yorumun ("ICU'ya bağlı DEĞİL") gerekçesi
// `toLocaleString()`in SUNUCU yereline göre sessizce değişmesiydi — haklı bir
// korku. Burada yerel HER ÇAĞRIDA açıkça veriliyor (`Intl.X(yerel)`), yani
// çıktı sunucu ortamından bağımsız ve testle kilitli.
//
// ⚠ TAKVİM VE RAKAM ZORLAMASI — hepsi CANLI ÇIKTIDA yakalandı, varsayılmadı.
// Ölçü basit ve testle kilitli: "2013-09-29" biçimlendiğinde metinde **2013**
// geçmeli. Geçmiyorsa ya takvim ya rakam sistemi bizim istediğimiz değil.
//   · `fa-IR`  -> Hicri-şemsi takvim + Doğu Arap rakamı (`۱۹ مرداد ۱۳۹۷`)
//   · `th-TH`  -> **Budist takvim** (2013 yerine `2556`) — sayfanın başlığında
//                 TMDB'nin Gregoryen yılı (`(2008)`) durduğu için aynı sayfada
//                 iki farklı takvim çıkıyordu
//   · `bn-BD`, `mr-IN` -> Bengal/Devanagari rakamları (`২০১৩`, `२०१३`)
//   · `ar-SA`, `my-MM` -> Doğu Arap / Birman rakamları
// Yapımın yılı bir KİMLİK bilgisidir (aynı adlı iki dizi ancak yılla ayrışır);
// yerel rakam sistemi onu arama sorgusuyla eşleşmez hâle getiriyor.

// Uygulama dil kodu -> ICU yereli. TMDB kodundan TÜRETİLMEZ: TMDB `fil` için
// `tl-PH` istiyor ama ICU'da `fil` doğru koddur; `zh-CN`/`sr-RS` gibi bölge
// ekleri de ICU'da farklı davranıyor.
const ICU_YEREL = {
  tr: 'tr-TR', en: 'en-US', es: 'es-ES', de: 'de-DE', fr: 'fr-FR',
  it: 'it-IT', pt: 'pt-BR', ru: 'ru-RU', ja: 'ja-JP', ko: 'ko-KR',
  zh: 'zh-CN', ar: 'ar-SA-u-nu-latn', hi: 'hi-IN', nl: 'nl-NL', pl: 'pl-PL',
  sv: 'sv-SE', da: 'da-DK', fi: 'fi-FI', nb: 'nb-NO', cs: 'cs-CZ',
  el: 'el-GR', hu: 'hu-HU', ro: 'ro-RO', bg: 'bg-BG', uk: 'uk-UA',
  sr: 'sr-RS', he: 'he-IL', fa: 'fa-IR-u-ca-gregory-nu-latn', ur: 'ur-PK',
  bn: 'bn-BD-u-nu-latn', ta: 'ta-IN', te: 'te-IN', mr: 'mr-IN-u-nu-latn',
  gu: 'gu-IN',
  kn: 'kn-IN', ml: 'ml-IN', pa: 'pa-IN', th: 'th-TH-u-ca-gregory', vi: 'vi-VN',
  id: 'id-ID', ms: 'ms-MY', fil: 'fil-PH', sw: 'sw-KE', az: 'az-AZ',
  am: 'am-ET', my: 'my-MM-u-nu-latn',
};

const icuYerel = (dil) => ICU_YEREL[dil] || ICU_YEREL.tr;

// Biçimleyici önbelleği: `Intl.*` kurucuları pahalıdır (ilk çağrıda ~1 ms) ve
// SSS bir sayfada 6 tarih birden basabiliyor.
const _bicimBellek = new Map();
function _bicim(anahtar, uret) {
  let b = _bicimBellek.get(anahtar);
  if (!b) { b = uret(); _bicimBellek.set(anahtar, b); }
  return b;
}

/**
 * 'YYYY-MM-DD' -> o dilin UZUN tarihi. Geçersiz girdide '' (atmaz).
 *
 * `timeZone: 'UTC'` ŞART: `new Date('2018-08-10')` UTC gece yarısıdır ve
 * sunucu saat dilimi UTC'nin batısındaysa bir GÜN GERİ basılırdı.
 */
function seoTarih(iso, dil) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(iso ?? '').slice(0, 10));
  if (!m) return '';
  const ay = Number(m[2]);
  const gun = Number(m[3]);
  if (ay < 1 || ay > 12 || gun < 1 || gun > 31) return '';
  const y = icuYerel(dil);
  const b = _bicim(`t:${y}`, () => new Intl.DateTimeFormat(y, {
    day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC',
  }));
  return b.format(new Date(Date.UTC(Number(m[1]), ay - 1, gun)));
}

/** 894983373 -> "894.983.373" (tr) / "894,983,373" (en). Yoksa/0 ise ''. */
function seoSayi(sayi, dil) {
  const n = Math.round(Number(sayi));
  if (!Number.isFinite(n) || n <= 0) return '';
  const y = icuYerel(dil);
  return _bicim(`n:${y}`, () => new Intl.NumberFormat(y)).format(n);
}

/** Ondalıklı büyüklük: 2.8 -> "2,8" (tr) / "2.8" (en). */
function seoOndalik(sayi, dil) {
  const y = icuYerel(dil);
  return _bicim(`d:${y}`, () => new Intl.NumberFormat(y, {
    minimumFractionDigits: 0, maximumFractionDigits: 1,
  })).format(Number(sayi));
}

/**
 * ISO 3166 ülke kodu -> o dildeki ülke adı. Çözülemezse HAM KOD döner
 * (yanlış ad uydurmaktansa kod dursun — eski `SEO_ULKE_ADI` disiplini).
 */
function seoUlke(kod, dil) {
  const k = String(kod || '').toUpperCase();
  if (!/^[A-Z]{2}$/.test(k)) return k;
  // `ZZ` CLDR'de GEÇERLİ bir koddur ve "Bilinmeyen Bölge" diye çözülür —
  // yani `fallback: 'none'` onu elemez. Sayfaya "Bilinmeyen Bölge merkezli bir
  // yapım firması" yazmak uydurma bilgi olur; ham kod dursun.
  if (k === 'ZZ') return k;
  const y = icuYerel(dil);
  try {
    // `fallback: 'none'` ŞART: varsayılanda ICU bilinmeyen koda "Bilinmeyen
    // Bölge" / "Unknown Region" diyor ve bu, sayfaya BASILAN bir yalan olurdu.
    // Eski `SEO_ULKE_ADI` disiplini: çözülemeyen kod HAM kalır.
    const b = _bicim(`u:${y}`, () => new Intl.DisplayNames([y], {
      type: 'region', fallback: 'none',
    }));
    return b.of(k) || k;
  } catch (_) {
    return k;
  }
}

/**
 * Şablon doldurucu: `bic('{ad} kaç sezon?', { ad: 'Silo' })`.
 * Karşılığı OLMAYAN yer tutucu BOŞ dizgiye düşer — şablonda kalan `{x}`
 * kullanıcıya gösterilmesin (testle kilitli).
 */
function bic(sablon, degerler = {}) {
  return String(sablon ?? '')
    .replace(/\{(\w+)\}/g, (_, k) =>
      (degerler[k] === undefined || degerler[k] === null ? '' : String(degerler[k])))
    // ÇİFT NOKTA SADELEŞTİRME (29 Ağu 2026, canlı Rusça çıktıda yakalandı):
    // ICU Rusça/Ukraynaca uzun tarihi "15 июля 2010 г." diye bitiriyor ve
    // şablonun kendi noktası üstüne binince "…2010 г.." çıkıyordu. Aynı tuzak
    // "S.W.A.T." gibi noktayla biten YAPIM ADLARINDA da var.
    // YALNIZ boşluk/satır sonu ÖNCESİNDEKİ ikiliyi sadeleştirir: üç nokta
    // yerine tek karakterlik "…" kullanıldığı için ellipsis'e dokunmaz,
    // kelime ortasındaki noktalara da (URL, kısaltma) hiç bakmaz.
    .replace(/\.\.(?=\s|$)/g, '.');
}

