// <<<YENI-DIL-BURAYA>>>

// ===========================================================================
// KAPI: hangi dil CANLI?
// ===========================================================================
// Tabloda TAM karşılığı olan diller. `server.js` bu listeyi üç yerde okur:
//   1. dil önekli yol çözümü (`/en/icerik/...`),
//   2. hreflang kümesi (karşılıklı olmalı — eksik dil hiçbir sayfada geçmez),
//   3. dil başına site haritası.
// Üçü AYNI listeden beslendiği için ayrışamazlar.
const SEO_DILLER = Object.keys(SEO_DIL);

/** Bu dil için TAM bir metin tablosu var mı? */
const seoDilVar = (dil) => Object.prototype.hasOwnProperty.call(SEO_DIL, String(dil || ''));

/**
 * Dil tablosu. BİLİNMEYEN DİL tr'ye düşer — ama bu yol yalnız `/og/...`
 * öneksiz (Türkçe kök) istekler için geçerlidir; dil önekli URL zaten
 * `seoDilVar` süzgecinden geçmeden yönlendirilmez.
 */
const seoDil = (dil) => SEO_DIL[dil] || SEO_DIL.tr;

/**
 * Kanonik yolun dil önekli hâli. Türkçe KÖKTE kalır (önek YOK) —
 * `x-default` da odur.
 *
 * Karar (29 Ağu 2026, kullanıcı): DİZİN TABANLI şema. Sorgu parametreli
 * varyant (`?dil=de`) iki ayrı sebeple ölmüştü: (1) hiçbir motor onu ayrı
 * sayfa saymıyor, (2) nginx bot yolunda `proxy_pass http://…/og$uri;`
 * URI'sinde DEĞİŞKEN taşıdığı için sorgu dizesini EKLEMİYOR, yani `?dil=`
 * uca hiç ulaşmıyordu (ANAHTAR-KELIME-ENVANTERI §4.2 md.2).
 */
function seoDilliYol(yol, dil) {
  const y = String(yol || '/');
  if (!dil || dil === 'tr' || !seoDilVar(dil)) return y;
  return y === '/' ? `/${dil}` : `/${dil}${y}`;
}

/**
 * Yolun başındaki dil önekini AYIRIR: '/en/icerik/movie/559'
 *   -> { dil: 'en', yol: '/icerik/movie/559' }
 * Önek yoksa ya da bilinmeyen bir kodsa dil 'tr', yol DEĞİŞMEZ.
 *
 * ⚠ 'tr' ÖNEKİ KABUL EDİLMEZ: `/tr/icerik/...` diye bir kanonik yok; kabul
 * etseydik aynı sayfa iki adresten servis edilir, kanonik/hreflang halkası
 * kendi kendisiyle çelişirdi.
 */
function seoDilAyir(yol) {
  const m = /^\/([A-Za-z]{2,3})(\/.*)?$/.exec(String(yol || '/'));
  if (!m) return { dil: 'tr', yol: String(yol || '/') };
  const kod = m[1].toLowerCase();
  if (kod === 'tr' || !seoDilVar(kod)) return { dil: 'tr', yol: String(yol || '/') };
  return { dil: kod, yol: m[2] || '/' };
}

/**
 * Sağlayıcı parçalarını ayıran noktalı virgül. CJK'da Latin `;` metnin
 * içinde yabancı duruyor (canlı Japonca çıktıda görüldü); tam genişlikli
 * `；` doğru karakter. Yeni bir tablo anahtarı EKLENMEDİ: dilin kendi liste
 * ayracı (`ayrac`) zaten bu ayrımı taşıyor — `、` kullanan dil `；` kullanır.
 */
const seoSagAyrac = (dil) => (seoDil(dil).ayrac.trim() === '、' ? '；' : '; ');

export {
  SEO_DIL, SEO_DILLER, ICU_YEREL, seoSagAyrac,
  seoDil, seoDilVar, seoDilliYol, seoDilAyir,
  seoTarih, seoSayi, seoOndalik, seoUlke, bic, icuYerel,
};
